#!/usr/bin/env python3
"""
Proof-of-Concept: HTTP/2 TLS 1.3 Post-Handshake CertificateRequest Handling

This script demonstrates how an HTTP/2 client should handle a TLS 1.3
post-handshake CertificateRequest message according to RFC 9113 Section 9.2.3.

RFC 9113 states:
  "HTTP/2 clients MUST treat a TLS post-handshake CertificateRequest message
   as a connection error of type ENHANCE_YOUR_GRACE."

This PoC simulates a client connecting to a TLS 1.3 server that sends a
post-handshake CertificateRequest. A compliant client will terminate the
connection with an ENHANCE_YOUR_GRACE error. A non-compliant client may
ignore the request, continue processing, or mishandle the TLS alert.
"""

import ssl
import socket
import struct
import sys
import threading
import time

# TLS Record Layer Constants
TLS_RECORD_HEADER_LEN = 5
TLS_CONTENT_TYPE_HANDSHAKE = 22
TLS_CONTENT_TYPE_ALERT = 21
TLS_VERSION_1_3 = 0x0303

# TLS Handshake Message Types
HANDSHAKE_TYPE_CERTIFICATE_REQUEST = 13
HANDSHAKE_TYPE_FINISHED = 20

# TLS Alert Types
ALERT_LEVEL_FATAL = 2
ALERT_DESCRIPTION_UNEXPECTED_MESSAGE = 10
ALERT_DESCRIPTION_ENHANCE_YOUR_GRACE = 120  # RFC 9113 specific

def parse_tls_record(data):
    """Parse a TLS record header and return content type, version, and length."""
    if len(data) < TLS_RECORD_HEADER_LEN:
        return None, None, None
    content_type = data[0]
    version = struct.unpack('!H', data[1:3])[0]
    length = struct.unpack('!H', data[3:5])[0]
    return content_type, version, length

def send_tls_alert(sock, alert_type):
    """Send a TLS alert message."""
    alert_data = struct.pack('!BB', ALERT_LEVEL_FATAL, alert_type)
    record = struct.pack('!BBH', TLS_CONTENT_TYPE_ALERT, TLS_VERSION_1_3, len(alert_data)) + alert_data
    sock.sendall(record)

def simulate_client_connection(server_host, server_port):
    """
    Simulate an HTTP/2 client connecting to a TLS 1.3 server.
    Monitors for post-handshake CertificateRequest messages.
    """
    # Create a raw socket for low-level TLS interaction
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(10)
    
    try:
        sock.connect((server_host, server_port))
        print(f"[*] Connected to {server_host}:{server_port}")
        
        # Wrap with SSL for TLS 1.3 handshake
        context = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
        context.check_hostname = False
        context.verify_mode = ssl.CERT_NONE
        context.minimum_version = ssl.TLSVersion.TLSv1_3
        
        ssl_sock = context.wrap_socket(sock, server_hostname=server_host)
        print("[+] TLS 1.3 handshake completed successfully")
        
        # After handshake, monitor for post-handshake messages
        # In a real scenario, the server would send a CertificateRequest
        # We simulate this by reading from the socket
        
        print("[*] Waiting for post-handshake messages...")
        
        # Read data from the socket
        data = ssl_sock.recv(4096)
        
        if not data:
            print("[!] Connection closed by server")
            return
        
        # Parse the received data
        content_type, version, length = parse_tls_record(data)
        
        if content_type == TLS_CONTENT_TYPE_HANDSHAKE:
            # Check if it's a CertificateRequest
            if len(data) > TLS_RECORD_HEADER_LEN:
                handshake_type = data[TLS_RECORD_HEADER_LEN]
                if handshake_type == HANDSHAKE_TYPE_CERTIFICATE_REQUEST:
                    print("[!] Received post-handshake CertificateRequest")
                    print("[*] According to RFC 9113, client MUST treat this as ENHANCE_YOUR_GRACE")
                    
                    # Compliant behavior: Send ENHANCE_YOUR_GRACE alert and close
                    send_tls_alert(sock, ALERT_DESCRIPTION_ENHANCE_YOUR_GRACE)
                    print("[+] Sent ENHANCE_YOUR_GRACE alert")
                    return
        
        print("[*] No post-handshake CertificateRequest received")
        
    except ssl.SSLError as e:
        print(f"[!] SSL Error: {e}")
    except socket.timeout:
        print("[!] Connection timed out")
    except Exception as e:
        print(f"[!] Unexpected error: {e}")
    finally:
        sock.close()
        print("[*] Connection closed")

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <server_host> <server_port>")
        print("Example: python3 poc_http2_tls13_post_handshake_cert_req.py localhost 443")
        sys.exit(1)
    
    server_host = sys.argv[1]
    server_port = int(sys.argv[2])
    
    print(f"[*] Starting HTTP/2 TLS 1.3 Post-Handshake CertificateRequest PoC")
    print(f"[*] Target: {server_host}:{server_port}")
    
    simulate_client_connection(server_host, server_port)

if __name__ == "__main__":
    main()
